lessons.push({
  title: "Inheritance: Single, Multilevel and Hierarchical, super() and Overriding",
  minutes: 50,
  learn: ["Create a subclass that reuses and extends a parent class", "Override methods and call the parent with super()", "Recognise single, multilevel and hierarchical inheritance", "Use isinstance and issubclass; decide when inheritance fits"],
  why: "Inheritance avoids copy-pasting shared code: the common part lives in a parent class and each specialised class adds only what differs.",
  realWorld: "An Employee Management system: every Employee has a name and salary; a Manager is an Employee with a bonus; a Developer is an Employee with a skill list.",
  simple: "<code>class Manager(Employee):</code> makes Manager a <strong>child</strong> of Employee. It gets all Employee's attributes and methods, and may <strong>override</strong> any of them. <code>super()</code> reaches the parent's version.",
  detail: `${table(["Kind", "Shape", "Example"], [["Single", "one parent, one child", "Manager(Employee)"], ["Multilevel", "chain: grandparent &rarr; parent &rarr; child", "Employee &rarr; Manager &rarr; Director"], ["Hierarchical", "one parent, several children", "Employee &rarr; Manager, Developer, Intern"], ["Multiple", "several parents (next lesson)", "class C(A, B)"]])}
<h3>Rules</h3>
<ul><li>A child is-a parent: a Manager <em>is an</em> Employee. If that sentence is false, do not use inheritance.</li><li>A child that defines <code>__init__</code> must usually call <code>super().__init__(...)</code> so the parent's setup runs.</li><li><strong>Overriding</strong>: define a method with the same name in the child to replace the parent's behaviour. Use <code>super().method()</code> to extend rather than replace it.</li><li><code>isinstance(obj, Employee)</code> is True for a Manager object; <code>type(obj) == Employee</code> is not. Prefer <code>isinstance</code>. <code>issubclass(Manager, Employee)</code> compares classes.</li><li>Every class ultimately inherits from <code>object</code>.</li></ul>
<h3>Liskov substitution (preview)</h3>
<p>Code written for the parent should work unchanged with any child. If a child must reject things the parent accepts, the hierarchy is probably wrong.</p>
<h3>When not to inherit</h3>
<p>Do not inherit only to reuse code when the &quot;is-a&quot; relation is false (a <code>Stack</code> is not a <code>list</code>). Use composition (a Stack <em>has</em> a list), covered in the abstraction lesson.</p>`,
  syntax: { code: `class Employee:\n    def __init__(self, name, base):\n        self.name, self.base = name, base\n    def salary(self):\n        return self.base\n\nclass Manager(Employee):\n    def __init__(self, name, base, bonus):\n        super().__init__(name, base)\n        self.bonus = bonus\n    def salary(self):\n        return super().salary() + self.bonus`, note: "super() finds the next class in the lookup order." },
  diagram: graph("Hierarchical and multilevel inheritance", "Employee at the top; Manager, Developer and Intern inherit from it; Director inherits from Manager.", 640, 270,
    [{ id: "e", k: "term", t: "Employee\nname, base, salary()", x: 320, y: 40, w: 220, h: 56 }, { id: "m", k: "proc", t: "Manager\n+ bonus", x: 110, y: 150, w: 150, h: 50 }, { id: "d", k: "proc", t: "Developer\n+ skills", x: 320, y: 150, w: 150, h: 50 }, { id: "i", k: "proc", t: "Intern\n- reduced pay", x: 530, y: 150, w: 150, h: 50 }, { id: "r", k: "proc", t: "Director\n+ stock", x: 110, y: 240, w: 150, h: 46 }],
    [{ from: "m", to: "e" }, { from: "d", to: "e" }, { from: "i", to: "e" }, { from: "r", to: "m" }]),
  example: { code: `class Employee:\n    def __init__(self, name, base):\n        self.name = name\n        self.base = base\n\n    def salary(self):\n        return self.base\n\n    def describe(self):\n        return f"{self.name} earns {self.salary()}"\n\nclass Manager(Employee):\n    def __init__(self, name, base, bonus):\n        super().__init__(name, base)\n        self.bonus = bonus\n\n    def salary(self):\n        return super().salary() + self.bonus\n\nclass Director(Manager):\n    def salary(self):\n        return super().salary() * 2\n\nstaff = [Employee("Asha", 50000), Manager("Ravi", 80000, 10000), Director("Zoya", 90000, 10000)]\nfor person in staff:\n    print(person.describe())\nprint(sum(p.salary() for p in staff))\nprint(isinstance(staff[2], Employee), isinstance(staff[0], Manager), issubclass(Director, Manager))\nprint(Director.__mro__[0].__name__, Director.__mro__[1].__name__)`, out: `Asha earns 50000\nRavi earns 90000\nZoya earns 200000\n340000\nTrue False True\nDirector Manager` },
  lineByLine: [["class Manager(Employee)", "Manager inherits name, base, salary and describe."], ["super().__init__(name, base)", "Runs the parent's constructor for the shared part."], ["super().salary() + self.bonus", "Extends the parent's calculation."], ["Director(Manager) ... * 2", "A multilevel chain: Director builds on Manager, which builds on Employee."], ["person.describe()", "describe is written once in Employee, but calls the right <code>salary()</code> for each object."], ["isinstance(...)", "A Director is an Employee; an Employee is not a Manager."]],
  dryRun: { intro: "<code>Director(\"Zoya\", 90000, 10000).salary()</code>:", headers: ["Call", "Returns"], rows: [["Director.salary", "calls super().salary() (Manager) then * 2"], ["Manager.salary", "calls super().salary() (Employee) + bonus"], ["Employee.salary", "90000"], ["Manager adds bonus", "100000"], ["Director doubles", "200000"]] },
  realExample: { intro: "Same interface, different pay rules: payroll code does not care which kind of employee it receives.", code: `class Employee:\n    def __init__(self, name, base):\n        self.name, self.base = name, base\n    def salary(self):\n        return self.base\n\nclass Intern(Employee):\n    def salary(self):\n        return self.base // 2\n\nclass Developer(Employee):\n    def __init__(self, name, base, skills):\n        super().__init__(name, base)\n        self.skills = skills\n    def salary(self):\n        return self.base + 5000 * len(self.skills)\n\nteam = [Intern("Kiran", 20000), Developer("Meera", 60000, ["python", "sql"])]\nprint([e.salary() for e in team])`, out: `[10000, 70000]` },
  mistakes: ["Forgetting <code>super().__init__()</code>, leaving parent attributes missing.", "Using inheritance when the relation is &quot;has-a&quot;.", "Deep hierarchies that nobody can follow.", "Changing the meaning of an inherited method so callers break.", "Calling the parent class by name (<code>Employee.__init__(self, ...)</code>) instead of <code>super()</code> in multiple-inheritance code."],
  practices: ["Keep hierarchies shallow (two or three levels).", "Use <code>super()</code>.", "Put shared code in the parent, differences in children.", "Prefer composition when unsure."],
  interview: ["What is method overriding?", "What does super() do?", "What are the types of inheritance?", "Difference between isinstance and type()?"],
  practiceQs: ["Add a Vehicle hierarchy: Vehicle, Car(Vehicle), Truck(Vehicle) with a wheels attribute.", "What does a child inherit if it defines no __init__?", "Write describe() in the parent and override it in a child extending the text with super().", "Why is Stack(list) a questionable design?"],
  revision: ["class Child(Parent).", "super().__init__() and super().method().", "Override = same name in child.", "is-a → inheritance; has-a → composition."],
  hinglish: "Inheritance mein child class parent ki cheezein le leti hai aur apna kuch jod sakti hai. super() se parent ka version chalate hain. Agar 'child IS-A parent' sach nahi hai to inheritance mat use karo, composition use karo.",
  quiz: [
    mcq("What does super().__init__(name) do in a child class?", ["Creates a new class", "Runs the parent's constructor", "Deletes name", "Imports the parent"], 1, "It runs the parent's setup."),
    mcq("What is printed?\n\nclass A:\n    def hi(self): return \"A\"\nclass B(A):\n    def hi(self): return \"B\"\nprint(B().hi())", ["A", "B", "AB", "Error"], 1, "The child's method overrides the parent's.", "OUTPUT_PREDICTION"),
    mcq("A class inheriting from one parent, which inherits from another, is:", ["Single", "Multilevel", "Hierarchical", "Multiple"], 1, "A chain of parents is multilevel inheritance."),
    mcq("What is isinstance(Manager(...), Employee)?", ["True", "False", "Error", "None"], 0, "A child instance is also an instance of its parent class."),
    mcq("When is inheritance the wrong tool?", ["When the relation is has-a", "When there are two classes", "When code is reused", "When methods are overridden"], 0, "Use composition for has-a.")
  ],
  tasks: [task("Payroll with inheritance", "Read n, then n lines of the form name base type where type is dev, manager or intern. Create objects using inheritance and override salary(): a dev earns the base, a manager earns base * 6 // 5 (20% more), an intern earns base // 2. Print the total payroll as an integer.", "n = int(input())\n# define Employee, Manager, Intern, read the lines and print the total\n", `class Employee:\n    def __init__(self, name, base):\n        self.name, self.base = name, base\n    def salary(self):\n        return self.base\n\nclass Manager(Employee):\n    def salary(self):\n        return self.base * 6 // 5\n\nclass Intern(Employee):\n    def salary(self):\n        return self.base // 2\n\nkinds = {"dev": Employee, "manager": Manager, "intern": Intern}\nn = int(input())\ntotal = 0\nfor _ in range(n):\n    name, base, kind = input().split()\n    total += kinds[kind](name, int(base)).salary()\nprint(total)`, [["3\nAsha 50000 dev\nRavi 80000 manager\nZoya 20000 intern", "156000"], ["1\nKiran 10000 dev", "10000"]], [["3\nAsha 50000 dev\nRavi 80000 manager\nZoya 20000 intern", "156000"], ["1\nKiran 10000 dev", "10000"], ["2\nA 100 manager\nB 100 manager", "240"], ["2\nA 99 intern\nB 5 intern", "51"]])],
});

